#!/usr/bin/env python3
from __future__ import annotations

from pathlib import Path
from xml.sax.saxutils import escape

ROOT = Path(__file__).resolve().parents[1]
LESSON = ROOT / "voice" / "modules" / "module-01" / "lesson-1.1"

TEXTS = [
"""Добро пожаловать в Академию Джемикс. Сегодня начинается не просто знакомство с насосами, а формирование профессионального подхода к работе с инженерным оборудованием. Представьте обычный загородный дом: кухня, душ, отопление, полив участка. Всё это должно работать стабильно каждый день. Но за привычным комфортом всегда стоит правильно подобранное оборудование. Наша задача — научиться видеть не отдельную модель в каталоге, а всю систему целиком. Уже после этого урока вы будете понимать, почему грамотный подбор начинается не с мощности, цены или популярности насоса, а с задачи клиента. Это фундамент, на котором будет строиться вся дальнейшая Академия Джемикс.""",
"""Что на самом деле покупает клиент? Формально — насос. Но в реальности он покупает воду в кране, нормальный душ, полив участка, сухой подвал или тепло в доме. Насос для него — только средство достижения результата. Поэтому профессиональный менеджер должен говорить не только о товаре, но и о решении. Когда клиент произносит: «Мне нужен насос», это ещё не запрос на конкретную модель. Это начало диагностики. Нужно понять, что человек хочет получить в итоге, где будет работать оборудование и какие условия существуют на объекте. Такой подход сразу меняет качество консультации и формирует доверие.""",
"""Насосы окружают нас гораздо чаще, чем кажется. Скважинный насос поднимает воду с глубины. Насосная станция поддерживает водоснабжение дома. Циркуляционный насос перемещает теплоноситель по системе отопления. Дренажный насос удаляет воду из подвала или приямка. Канализационная установка помогает там, где стоки невозможно отвести самотёком. Для клиента всё это выглядит как обычный бытовой комфорт. Для специалиста — как система задач, каждая из которых требует своего оборудования. Поэтому знание насосов — это не заучивание ассортимента, а умение быстро определить, какое инженерное решение необходимо в конкретной ситуации.""",
"""Если объяснить простыми словами, насос передаёт жидкости энергию. Пока вода находится в колодце, скважине или ёмкости, она сама не попадёт к потребителю в нужном объёме и под нужным давлением. Насос создаёт движение, помогает преодолеть высоту подъёма и сопротивление трубопровода. Именно поэтому его часто сравнивают с сердцем системы. Но важно понимать: насос не создаёт воду и не исправляет ошибки всей системы автоматически. Он работает в конкретных условиях. Если условия определены неверно, даже качественное оборудование не даст ожидаемого результата. Профессионал сначала изучает систему, а уже затем выбирает насос.""",
"""Одна из самых распространённых ошибок — выбирать насос по мощности двигателя. Клиент видит больше ватт и делает вывод: значит, этот насос лучше. Но мощность сама по себе не отвечает на главный вопрос — сможет ли оборудование обеспечить необходимый расход и напор в заданной системе. Избыточный насос может работать неэффективно, чаще включаться и выключаться, создавать лишнее давление и расходовать больше электроэнергии. Слабый насос, наоборот, не даст нужного результата. Поэтому задача менеджера — перевести разговор с абстрактного «мощнее» на конкретные рабочие параметры. Сначала выясняем условия, потом смотрим характеристики.""",
"""Рассмотрим типичную ситуацию. Покупатель приходит в магазин и просит хороший насос. Менеджер хочет помочь быстро и предлагает популярную модель. Через несколько дней клиент возвращается: насос не обеспечивает воду в доме. Оборудование исправно, но его подобрали без учёта глубины источника, длины трассы и количества потребителей. В результате магазин получает возврат, менеджер тратит время, а клиент теряет доверие. Этой ситуации можно было избежать несколькими вопросами в начале разговора. Главный вывод: скорость консультации определяется не тем, как быстро вы назвали модель, а тем, насколько точно вы поняли задачу.""",
"""Профессиональный консультант начинает с диагностики. Для чего нужен насос? Что именно он будет перекачивать? Откуда поступает вода? Куда её нужно подать? Какое расстояние и перепад высот между источником и потребителем? Сколько точек водоразбора может работать одновременно? Нужна ли автоматическая работа? Эти вопросы не усложняют продажу, а сокращают путь к правильному решению. Клиент видит, что перед ним специалист, который не угадывает, а анализирует. Именно этот навык отличает техническую консультацию от простой демонстрации товара.""",
"""Любой подбор можно представить как последовательный алгоритм. Сначала определяем задачу: подача чистой воды, откачивание загрязнённой воды, повышение давления или циркуляция. Затем уточняем среду, источник, точку подачи и режим работы. После этого переходим к расходу и напору, учитываем длину трубопровода, высоту подъёма и потери. И только когда исходные данные собраны, открываем каталог. Такой порядок защищает от случайного выбора. Запомните: каталог — это финальный инструмент подбора, а не его начало. Чем точнее исходные данные, тем увереннее рекомендация менеджера.""",
"""Теперь практический пример. Клиент говорит: «Нужен насос для дачи». Этого недостаточно. Для полива из бочки подойдёт одно решение. Для подачи воды из колодца глубиной шесть метров — другое. Для скважины глубиной пятьдесят метров — третье. А если насос должен одновременно снабжать дом и поливать участок, требования снова изменятся. Одна короткая фраза клиента может скрывать совершенно разные задачи. Поэтому не бойтесь уточнять. Хороший вопрос экономит больше времени, чем десять минут поиска по каталогу.""",
"""Проверим логику. Клиент просит насос для воды. Что нужно сделать первым? Не выбирать самый мощный, не спрашивать только бюджет и не предлагать товар со склада. Первый шаг — уточнить назначение, источник, условия работы и ожидаемый результат. Правильная консультация начинается с понимания объекта. Даже если клиент торопится, несколько ключевых вопросов обязательны. Объясните, что они нужны не для усложнения покупки, а чтобы оборудование действительно справилось с задачей. Такой комментарий обычно воспринимается позитивно и укрепляет доверие.""",
"""Самая важная формула этого урока звучит так: не насос выбирает задачу, а задача выбирает насос. Сначала мы определяем, что должна получить система. Затем рассчитываем необходимые рабочие параметры. И только после этого ищем модель, которая соответствует расчёту. Если начать с понравившегося товара и попытаться подогнать под него объект, риск ошибки резко возрастает. Этот принцип одинаково работает для простого поливочного насоса и для сложной системы водоснабжения. Именно его нужно сохранить как профессиональную привычку.""",
"""Насосы решают разные задачи. Скважинные поднимают воду с большой глубины. Колодезные работают в источниках с более широким диаметром. Поверхностные располагаются вне воды и имеют ограничения по всасыванию. Дренажные откачивают загрязнённую воду. Фекальные рассчитаны на более сложные стоки. Циркуляционные обеспечивают движение теплоносителя. Повышающие помогают там, где давление уже существующей сети недостаточно. Эти группы нельзя считать взаимозаменяемыми. У каждой есть собственная конструкция и допустимые условия работы.""",
"""Почему у Джемикс широкий ассортимент? Не потому, что покупателю нужно показать как можно больше моделей. Разные объекты требуют разных решений. Глубина источника, качество воды, требуемая производительность, режим работы и способ монтажа могут существенно отличаться. Ассортимент позволяет подобрать оборудование под реальные условия, а не заставлять один тип насоса выполнять несвойственную задачу. Для менеджера широта линейки становится преимуществом только тогда, когда он умеет правильно классифицировать запрос клиента.""",
"""Рассмотрим ошибку из практики. Клиент приобретает поверхностный насос для глубокой скважины, потому что модель доступна по цене и имеет хорошую мощность. После установки вода не поступает. Насос исправен, но физические ограничения поверхностного всасывания не позволяют решить задачу. Это важный пример: техническая ошибка возникает ещё до покупки, на этапе неправильного определения группы оборудования. Правильно заданный вопрос о глубине источника сразу исключил бы неподходящий вариант. Знание менеджера в такой ситуации напрямую предотвращает возврат и финансовые потери.""",
"""Зафиксируем пять правил. Первое: универсального насоса не существует. Второе: подбор начинается с задачи. Третье: мощность двигателя не заменяет расход и напор. Четвёртое: среда и условия эксплуатации определяют допустимую группу оборудования. Пятое: хороший консультант предлагает решение, а не просто товар. Эти правила просты, но именно их нарушение приводит к большинству ошибок новичков. Используйте их как внутренний фильтр перед каждой рекомендацией.""",
"""Проверка. Можно ли правильно подобрать насос только по мощности? Нет. Мощность показывает потребление и возможности двигателя, но не описывает полностью рабочую точку насоса. Для подбора нужны как минимум задача, среда, расход и напор. Кроме того, важно учитывать источник, длину трассы, перепад высот, диаметр труб и режим работы. Если клиент сравнивает только ватты, объясните, что это похоже на выбор автомобиля только по объёму двигателя без учёта назначения. Профессиональная консультация переводит разговор к параметрам системы.""",
"""Мини-чек-лист первого разговора. Уточните назначение насоса. Определите тип жидкости и степень её загрязнения. Выясните источник и глубину. Спросите, куда и на какое расстояние нужно подавать воду. Определите количество потребителей и желаемый режим работы. Уточните особенности монтажа, электропитание и необходимость автоматики. Не обязательно задавать все вопросы одной длинной анкетой. Ведите диалог естественно, но к моменту подбора у вас должна сложиться целостная картина объекта.""",
"""Почему так важно знать среду перекачивания? Потому что чистая вода, загрязнённая вода, сточные воды и теплоноситель предъявляют разные требования к конструкции насоса. Размер допустимых включений, материалы, охлаждение двигателя и геометрия рабочего колеса могут отличаться. Насос, рассчитанный на чистую воду, может быстро выйти из строя при работе с песком или крупными частицами. Поэтому вопрос «что именно будем перекачивать» должен звучать в начале консультации, а не после выбора модели.""",
"""Напор связан со способностью насоса преодолевать высоту и сопротивление системы. Это не просто вертикальная высота от воды до крана. В расчёте учитываются также длина трубопровода, повороты, арматура, фильтры и необходимое давление у потребителя. Подробные расчёты мы разберём позже. Сейчас важно понять принцип: вода теряет энергию по пути, и насос должен компенсировать эти потери. Поэтому одинаковая высота объекта ещё не означает одинаковые требования к насосу.""",
"""Подведём итог. Насос передаёт жидкости энергию и обеспечивает её движение. Но правильная модель определяется не рекламой, не максимальной мощностью и не самой низкой ценой. Подбор начинается с задачи, среды, расхода и напора. Затем учитываются условия монтажа и режим эксплуатации. После этого выбирается оборудование. Уже сейчас вы знаете главный профессиональный принцип Академии Джемикс: сначала понять систему, затем рекомендовать решение. В следующем уроке мы подробно разберём расход, напор и давление — параметры, на которых строится технически грамотный подбор.""",
]


def make_ssml(text: str) -> str:
    sentences = [s.strip() for s in text.replace("!", ".").replace("?", ".").split(".") if s.strip()]
    body = []
    for i, sentence in enumerate(sentences):
        pause = "650ms" if i == 0 else "420ms"
        body.append(f"{escape(sentence)}.<break time=\"{pause}\"/>")
    return (
        '<speak><prosody rate="92%" pitch="-1st">'
        + " ".join(body)
        + "</prosody></speak>"
    )


def main() -> None:
    LESSON.mkdir(parents=True, exist_ok=True)
    if len(TEXTS) != 20:
        raise SystemExit(f"Expected 20 texts, found {len(TEXTS)}")
    for index, text in enumerate(TEXTS, 1):
        path = LESSON / f"slide{index:02d}.ssml"
        path.write_text(make_ssml(text), encoding="utf-8")
        print(f"OK: {path.relative_to(ROOT)}")
    print("Prepared 20 expert SSML files for lesson 1.1")


if __name__ == "__main__":
    main()
